use super::*;

#[derive(Clone, Copy, Deserialize, Serialize)] #[serde(rename_all="snake_case")] pub enum OpportunityStatus { Active, Expired, Removed, Rejected }
#[derive(Clone, Copy, Deserialize, Serialize)] #[serde(rename_all="snake_case")] pub enum OpportunityRecommendation { ActNow, Review, Watch, Dismiss }
#[derive(Clone, Copy, Deserialize, Serialize)] #[serde(rename_all="snake_case")] pub enum NotificationStatus { Unread, Read }
#[derive(Clone, Copy, Deserialize, Serialize)] #[serde(rename_all="snake_case")] pub enum NotificationPriority { Normal, High, Critical }
#[derive(Clone, Copy, Deserialize, Serialize, PartialEq)] #[serde(rename_all="snake_case")] pub enum NotificationKind { Intelligence, Opportunity }

#[derive(Deserialize)] struct BookmarkResponse { id:String,document_id:String,note:Option<String>,title:String,canonical_url:String,analysis_id:Option<String>,radar_id:Option<String>,summary:Option<String>,category:Option<String>,radar_score:Option<DecimalValue>,recommendation:Option<Recommendation>,created_at:String,updated_at:String }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct BookmarkView { id:String,document_id:String,note:Option<String>,title:String,canonical_url:String,analysis_id:Option<String>,radar_id:Option<String>,summary:Option<String>,category:Option<String>,radar_score:Option<f64>,recommendation:Option<Recommendation>,created_at:String,updated_at:String }
#[derive(Deserialize)] struct BookmarkPageResponse { items:Vec<BookmarkResponse>,page:i64,page_size:i64,total:i64 }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct BookmarkPageView { items:Vec<BookmarkView>,page:i64,page_size:i64,total:i64 }
#[derive(Deserialize)] #[serde(rename_all="camelCase",deny_unknown_fields)] pub struct BookmarkCreateInput { document_id:String,note:Option<String> }
#[derive(Deserialize)] #[serde(rename_all="camelCase",deny_unknown_fields)] pub struct BookmarkUpdateInput { note:Option<String> }

#[derive(Deserialize)] #[serde(rename_all="camelCase",deny_unknown_fields)] pub struct MemorySearchInput { query:String,top_k:i64,radar_id:Option<String>,date_from:Option<String>,date_to:Option<String>,bookmarked_only:bool }
#[derive(Deserialize)] struct MemorySearchResponse { items:Vec<MemorySearchResponseItem>,query:String,top_k:i64 }
#[derive(Deserialize)] struct MemorySearchResponseItem { analysis_id:String,document_id:String,radar_id:String,title:String,canonical_url:String,summary:Option<String>,category:Option<String>,radar_score:Option<DecimalValue>,recommendation:Option<Recommendation>,excerpt:String,similarity:DecimalValue,occurred_at:String,bookmarked:bool }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct MemorySearchView { items:Vec<MemorySearchItemView>,query:String,top_k:i64 }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct MemorySearchItemView { analysis_id:String,document_id:String,radar_id:String,title:String,canonical_url:String,summary:Option<String>,category:Option<String>,radar_score:Option<f64>,recommendation:Option<Recommendation>,excerpt:String,similarity:f64,occurred_at:String,bookmarked:bool }

