#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct OpportunityScoreView { id:String,radar_id:String,score_version:String,hard_filter_passed:bool,disqualifiers:Vec<Value>,fit:Option<i64>,expected_value:Option<i64>,completion_probability:Option<i64>,effort_efficiency:Option<i64>,time_to_delivery:Option<i64>,competition:Option<i64>,ambiguity:Option<i64>,risk:Option<i64>,overall_score:Option<f64>,recommendation:OpportunityRecommendation,reason:String,scored_at:String }
#[derive(Deserialize)] struct OpportunityResponse { id:String,source_id:String,title:String,platform:Option<String>,description:String,budget_min:Option<DecimalValue>,budget_max:Option<DecimalValue>,currency:Option<String>,skills:Vec<Value>,deadline:Option<String>,published_at:Option<String>,estimated_effort_hours:Option<DecimalValue>,delivery_type:Option<String>,profile_version:String,source_url:String,status:OpportunityStatus,created_at:String,updated_at:String,score:Option<OpportunityScoreResponse> }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct OpportunityView { id:String,source_id:String,title:String,platform:Option<String>,description:String,budget_min:Option<f64>,budget_max:Option<f64>,currency:Option<String>,skills:Vec<Value>,deadline:Option<String>,published_at:Option<String>,estimated_effort_hours:Option<f64>,delivery_type:Option<String>,profile_version:String,source_url:String,status:OpportunityStatus,created_at:String,updated_at:String,score:Option<OpportunityScoreView> }
#[derive(Deserialize)] struct OpportunityPageResponse { items:Vec<OpportunityResponse>,page:i64,page_size:i64,total:i64 }
