#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct NotificationView { id:String,kind:NotificationKind,analysis_id:Option<String>,opportunity_id:Option<String>,title:String,content:String,priority:NotificationPriority,reason:String,url:Option<String>,status:NotificationStatus,created_at:String,read_at:Option<String> }
#[derive(Deserialize)] struct NotificationPageResponse { items:Vec<NotificationResponse>,page:i64,page_size:i64,total:i64 }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct NotificationPageView { items:Vec<NotificationView>,page:i64,page_size:i64,total:i64 }
#[derive(Deserialize)] #[serde(rename_all="camelCase",deny_unknown_fields)] pub struct NotificationQuery { page:i64,page_size:i64,status:Option<NotificationStatus>,priority:Option<NotificationPriority> }
#[derive(Deserialize)] struct NotificationReadAllResponse { updated_count:i64,read_at:String }
#[derive(Serialize)] #[serde(rename_all="camelCase")] pub struct NotificationReadAllView { updated_count:i64,read_at:String }

fn optional_note(value:Option<String>)->Result<Option<String>,BridgeError>{value.map(|value|{let value=value.trim().to_string();if value.chars().count()>4000{Err(BridgeError::local("invalid_input","Bookmark note is too long"))}else if value.is_empty(){Ok(None)}else{Ok(Some(value))}}).transpose().map(|value|value.flatten())}
fn valid_datetime(value:&str)->bool{value.len()<=64&&value.contains('T')&&(value.ends_with('Z')||value.rfind('+').is_some_and(|index|index>value.find('T').unwrap_or(0))||value.rfind('-').is_some_and(|index|index>value.find('T').unwrap_or(0)))}
fn optional_decimal(value:Option<DecimalValue>,label:&str)->Result<Option<f64>,BridgeError>{value.map(|value|{let parsed=match value{DecimalValue::String(value)=>value.parse::<f64>(),DecimalValue::Number(value)=>Ok(value)}.map_err(|_|BridgeError::local("invalid_response",format!("Backend returned an invalid {label}")))?;if !parsed.is_finite()||parsed<0.0{return Err(BridgeError::local("invalid_response",format!("Backend returned an invalid {label}")));}Ok(parsed)}).transpose()}
fn score_component(value:Option<i64>)->Result<Option<i64>,BridgeError>{if value.is_some_and(|value|!(0..=100).contains(&value)){Err(BridgeError::local("invalid_response","Backend returned an invalid opportunity score component"))}else{Ok(value)}}
fn page_ok(page:i64,size:i64,total:i64,len:usize,expected_page:i64,expected_size:i64)->bool{page==expected_page&&size==expected_size&&total>=0&&len<=size as usize&&len as i64<=total}
fn bounded_values(values:&[Value])->bool{values.len()<=100&&values.iter().all(|value|serde_json::to_vec(value).is_ok_and(|encoded|encoded.len()<=16*1024))}

impl ApiClient {
    fn bookmark_view(value:BookmarkResponse)->Result<BookmarkView,BridgeError>{canonical_radar_id(&value.id)?;canonical_radar_id(&value.document_id)?;if let Some(id)=value.analysis_id.as_deref(){canonical_radar_id(id)?;}if let Some(id)=value.radar_id.as_deref(){canonical_radar_id(id)?;}Ok(BookmarkView{id:value.id,document_id:value.document_id,note:value.note,title:value.title,canonical_url:value.canonical_url,analysis_id:value.analysis_id,radar_id:value.radar_id,summary:value.summary,category:value.category,radar_score:match value.radar_score{Some(score)=>Some(score.finite_score()?),None=>None},recommendation:value.recommendation,created_at:value.created_at,updated_at:value.updated_at})}
    async fn bookmarks(&self,page:i64,size:i64)->Result<BookmarkPageView,BridgeError>{let(page,size)=Self::pagination(page,size)?;let response:BookmarkPageResponse=self.protected_json_status(Operation::Bookmarks(page,size),StatusCode::OK).await?;if !page_ok(response.page,response.page_size,response.total,response.items.len(),page,size){return Err(BridgeError::local("invalid_response","Backend returned an invalid bookmark page"));}Ok(BookmarkPageView{items:response.items.into_iter().map(Self::bookmark_view).collect::<Result<_,_>>()?,page,page_size:size,total:response.total})}
    async fn create_bookmark(&self,input:BookmarkCreateInput)->Result<BookmarkView,BridgeError>{let document=canonical_radar_id(&input.document_id)?;let note=optional_note(input.note)?;let body=serde_json::to_vec(&json!({"document_id":document,"note":note})).map_err(|_|BridgeError::local("invalid_input","Bookmark could not be encoded"))?;let response:BookmarkResponse=self.protected_json_status_with_body(Operation::BookmarkCreate,StatusCode::CREATED,Some(body)).await?;if response.document_id!=document{return Err(BridgeError::local("invalid_response","Backend returned a mismatched bookmark"));}Self::bookmark_view(response)}
    async fn update_bookmark(&self,id:String,input:BookmarkUpdateInput)->Result<BookmarkView,BridgeError>{let id=canonical_radar_id(&id)?;let note=optional_note(input.note)?;let body=serde_json::to_vec(&json!({"note":note})).map_err(|_|BridgeError::local("invalid_input","Bookmark update could not be encoded"))?;let response:BookmarkResponse=self.protected_json_status_with_body(Operation::BookmarkUpdate(id.clone()),StatusCode::OK,Some(body)).await?;if response.id!=id{return Err(BridgeError::local("invalid_response","Backend returned a mismatched bookmark"));}Self::bookmark_view(response)}
    async fn delete_bookmark(&self,id:String)->Result<(),BridgeError>{self.protected_no_content(Operation::BookmarkDelete(canonical_radar_id(&id)?)).await}
    async fn search_memory(&self,mut input:MemorySearchInput)->Result<MemorySearchView,BridgeError>{input.query=input.query.trim().to_string();if !(1..=4000).contains(&input.query.chars().count())||!(1..=50).contains(&input.top_k){return Err(BridgeError::local("invalid_input","Memory search is outside the frozen contract"));}let radar=input.radar_id.map(|value|canonical_radar_id(&value)).transpose()?;for value in [input.date_from.as_deref(),input.date_to.as_deref()].into_iter().flatten(){if !valid_datetime(value){return Err(BridgeError::local("invalid_input","Memory search dates require a UTC offset"));}}let body=serde_json::to_vec(&json!({"query":input.query,"top_k":input.top_k,"radar_id":radar,"date_from":input.date_from,"date_to":input.date_to,"bookmarked_only":input.bookmarked_only})).map_err(|_|BridgeError::local("invalid_input","Memory search could not be encoded"))?;let response:MemorySearchResponse=self.protected_json_status_with_body(Operation::MemorySearch,StatusCode::OK,Some(body)).await?;if response.query!=input.query||response.top_k!=input.top_k||response.items.len()>input.top_k as usize{return Err(BridgeError::local("invalid_response","Backend returned a mismatched memory search"));}let items=response.items.into_iter().map(|value|{canonical_radar_id(&value.analysis_id)?;canonical_radar_id(&value.document_id)?;canonical_radar_id(&value.radar_id)?;let similarity=optional_decimal(Some(value.similarity),"memory similarity")?.unwrap();if similarity>1.0{return Err(BridgeError::local("invalid_response","Backend returned an invalid memory similarity"));}Ok(MemorySearchItemView{analysis_id:value.analysis_id,document_id:value.document_id,radar_id:value.radar_id,title:value.title,canonical_url:value.canonical_url,summary:value.summary,category:value.category,radar_score:match value.radar_score{Some(score)=>Some(score.finite_score()?),None=>None},recommendation:value.recommendation,excerpt:value.excerpt,similarity,occurred_at:value.occurred_at,bookmarked:value.bookmarked})}).collect::<Result<Vec<_>,BridgeError>>()?;Ok(MemorySearchView{items,query:response.query,top_k:response.top_k})}
    fn opportunity_path(query:OpportunityQuery)->Result<(String,i64,i64,Option<String>),BridgeError>{let(page,size)=Self::pagination(query.page,query.page_size)?;let radar=query.radar_id.map(|value|canonical_radar_id(&value)).transpose()?;if query.min_score.is_some_and(|value|!value.is_finite()||!(0.0..=100.0).contains(&value)){return Err(BridgeError::local("invalid_input","Opportunity score is outside the frozen contract"));}let currency=query.currency.map(|value|value.trim().to_string());if currency.as_ref().is_some_and(|value|value.len()!=3||!value.bytes().all(|byte|byte.is_ascii_uppercase()))||query.deadline.as_ref().is_some_and(|value|!valid_datetime(value)){return Err(BridgeError::local("invalid_input","Opportunity filters are outside the frozen contract"));}let mut url=Url::parse("http://localhost/opportunities").map_err(|_|BridgeError::local("client_setup","Opportunity query could not be built"))?;{let mut pairs=url.query_pairs_mut();pairs.append_pair("page",&page.to_string()).append_pair("page_size",&size.to_string());if let Some(value)=radar.as_deref(){pairs.append_pair("radar_id",value);}if let Some(value)=query.status{pairs.append_pair("status",match value{OpportunityStatus::Active=>"active",OpportunityStatus::Expired=>"expired",OpportunityStatus::Removed=>"removed",OpportunityStatus::Rejected=>"rejected"});}if let Some(value)=query.recommendation{pairs.append_pair("recommendation",match value{OpportunityRecommendation::ActNow=>"act_now",OpportunityRecommendation::Review=>"review",OpportunityRecommendation::Watch=>"watch",OpportunityRecommendation::Dismiss=>"dismiss"});}if let Some(value)=query.min_score{pairs.append_pair("min_score",&value.to_string());}if let Some(value)=currency.as_deref(){pairs.append_pair("currency",value);}if let Some(value)=query.deadline.as_deref(){pairs.append_pair("deadline",value);}}Ok((url.query().unwrap_or_default().to_string(),page,size,radar))}
    fn opportunity_view(value:OpportunityResponse,radar:Option<&str>)->Result<OpportunityView,BridgeError>{canonical_radar_id(&value.id)?;canonical_radar_id(&value.source_id)?;if !bounded_values(&value.skills){return Err(BridgeError::local("invalid_response","Backend returned invalid opportunity skills"));}let score=value.score.map(|score|{canonical_radar_id(&score.id)?;let radar_id=canonical_radar_id(&score.radar_id)?;if radar.is_some_and(|expected|expected!=radar_id){return Err(BridgeError::local("invalid_response","Backend returned an opportunity for a different Radar"));}if !bounded_values(&score.disqualifiers){return Err(BridgeError::local("invalid_response","Backend returned invalid opportunity disqualifiers"));}Ok(OpportunityScoreView{id:score.id,radar_id,score_version:score.score_version,hard_filter_passed:score.hard_filter_passed,disqualifiers:score.disqualifiers,fit:score_component(score.fit)?,expected_value:score_component(score.expected_value)?,completion_probability:score_component(score.completion_probability)?,effort_efficiency:score_component(score.effort_efficiency)?,time_to_delivery:score_component(score.time_to_delivery)?,competition:score_component(score.competition)?,ambiguity:score_component(score.ambiguity)?,risk:score_component(score.risk)?,overall_score:match score.overall_score{Some(value)=>Some(value.finite_score()?),None=>None},recommendation:score.recommendation,reason:score.reason,scored_at:score.scored_at})}).transpose()?;Ok(OpportunityView{id:value.id,source_id:value.source_id,title:value.title,platform:value.platform,description:value.description,budget_min:optional_decimal(value.budget_min,"opportunity minimum budget")?,budget_max:optional_decimal(value.budget_max,"opportunity maximum budget")?,currency:value.currency,skills:value.skills,deadline:value.deadline,published_at:value.published_at,estimated_effort_hours:optional_decimal(value.estimated_effort_hours,"opportunity effort")?,delivery_type:value.delivery_type,profile_version:value.profile_version,source_url:value.source_url,status:value.status,created_at:value.created_at,updated_at:value.updated_at,score})}
    async fn opportunities(&self,query:OpportunityQuery)->Result<OpportunityPageView,BridgeError>{let(path,page,size,radar)=Self::opportunity_path(query)?;let response:OpportunityPageResponse=self.protected_json_status(Operation::Opportunities(path),StatusCode::OK).await?;if !page_ok(response.page,response.page_size,response.total,response.items.len(),page,size){return Err(BridgeError::local("invalid_response","Backend returned an invalid opportunity page"));}Ok(OpportunityPageView{items:response.items.into_iter().map(|value|Self::opportunity_view(value,radar.as_deref())).collect::<Result<_,_>>()?,page,page_size:size,total:response.total})}
    async fn opportunity(&self,id:String)->Result<OpportunityView,BridgeError>{let id=canonical_radar_id(&id)?;let response:OpportunityResponse=self.protected_json_status(Operation::Opportunity(id.clone()),StatusCode::OK).await?;if response.id!=id{return Err(BridgeError::local("invalid_response","Backend returned a mismatched opportunity"));}Self::opportunity_view(response,None)}
    async fn action_payload(&self,id:String)->Result<ActionPayloadView,BridgeError>{let id=canonical_radar_id(&id)?;let response:ActionPayloadResponse=self.protected_json_status(Operation::ActionPayload(id.clone()),StatusCode::OK).await?;if response.opportunity_id!=id||response.payload.as_object().and_then(|value|value.get("requires_human_approval")).and_then(Value::as_bool)!=Some(true){return Err(BridgeError::local("invalid_response","Action payload identity or human approval requirement is invalid"));}Ok(ActionPayloadView{opportunity_id:response.opportunity_id,payload_version:response.payload_version,payload:response.payload,payload_hash:response.payload_hash,generated_at:response.generated_at})}
    fn notification_view(value:NotificationResponse)->Result<NotificationView,BridgeError>{canonical_radar_id(&value.id)?;let analysis=value.analysis_id.map(|id|canonical_radar_id(&id)).transpose()?;let opportunity=value.opportunity_id.map(|id|canonical_radar_id(&id)).transpose()?;let valid=match value.kind{NotificationKind::Intelligence=>analysis.is_some()&&opportunity.is_none(),NotificationKind::Opportunity=>analysis.is_none()&&opportunity.is_some()};if !valid{return Err(BridgeError::local("invalid_response","Notification target does not match its kind"));}Ok(NotificationView{id:value.id,kind:value.kind,analysis_id:analysis,opportunity_id:opportunity,title:value.title,content:value.content,priority:value.priority,reason:value.reason,url:value.url,status:value.status,created_at:value.created_at,read_at:value.read_at})}
    async fn notifications(&self,query:NotificationQuery)->Result<NotificationPageView,BridgeError>{let(page,size)=Self::pagination(query.page,query.page_size)?;let mut url=Url::parse("http://localhost/notifications").map_err(|_|BridgeError::local("client_setup","Notification query could not be built"))?;{let mut pairs=url.query_pairs_mut();pairs.append_pair("page",&page.to_string()).append_pair("page_size",&size.to_string());if let Some(value)=query.status{pairs.append_pair("status",match value{NotificationStatus::Unread=>"unread",NotificationStatus::Read=>"read"});}if let Some(value)=query.priority{pairs.append_pair("priority",match value{NotificationPriority::Normal=>"normal",NotificationPriority::High=>"high",NotificationPriority::Critical=>"critical"});}}let response:NotificationPageResponse=self.protected_json_status(Operation::Notifications(url.query().unwrap_or_default().to_string()),StatusCode::OK).await?;if !page_ok(response.page,response.page_size,response.total,response.items.len(),page,size){return Err(BridgeError::local("invalid_response","Backend returned an invalid notification page"));}Ok(NotificationPageView{items:response.items.into_iter().map(Self::notification_view).collect::<Result<_,_>>()?,page,page_size:size,total:response.total})}
    async fn read_notification(&self,id:String)->Result<NotificationView,BridgeError>{let id=canonical_radar_id(&id)?;let response:NotificationResponse=self.protected_json_status(Operation::NotificationRead(id.clone()),StatusCode::OK).await?;if response.id!=id||!matches!(response.status,NotificationStatus::Read){return Err(BridgeError::local("invalid_response","Backend returned a mismatched notification read"));}Self::notification_view(response)}
    async fn read_all_notifications(&self)->Result<NotificationReadAllView,BridgeError>{let response:NotificationReadAllResponse=self.protected_json_status(Operation::NotificationsReadAll,StatusCode::OK).await?;if response.updated_count<0||!valid_datetime(&response.read_at){return Err(BridgeError::local("invalid_response","Backend returned an invalid read-all response"));}Ok(NotificationReadAllView{updated_count:response.updated_count,read_at:response.read_at})}
}

#[cfg(test)]
impl ApiClient {
    pub(super) async fn product_test_contract(&self)->Result<Vec<Value>,BridgeError>{
        let bookmark=self.create_bookmark(BookmarkCreateInput{document_id:"00000000-0000-4000-8000-000000000051".into(),note:Some(" keep ".into())}).await?;
        let bookmark_id=bookmark.id.clone();
        let values=vec![
            serde_json::to_value(self.bookmarks(1,10).await?).unwrap(),
            serde_json::to_value(bookmark).unwrap(),
            serde_json::to_value(self.update_bookmark(bookmark_id.clone(),BookmarkUpdateInput{note:None}).await?).unwrap(),
            serde_json::to_value(self.search_memory(MemorySearchInput{query:" policy ".into(),top_k:5,radar_id:Some("00000000-0000-4000-8000-000000000011".into()),date_from:Some("2026-10-01T00:00:00Z".into()),date_to:Some("2026-10-21T00:00:00+08:00".into()),bookmarked_only:true}).await?).unwrap(),
            serde_json::to_value(self.opportunities(OpportunityQuery{page:1,page_size:10,radar_id:Some("00000000-0000-4000-8000-000000000011".into()),status:Some(OpportunityStatus::Active),recommendation:Some(OpportunityRecommendation::Review),min_score:Some(50.5),currency:Some("USD".into()),deadline:Some("2026-12-01T00:00:00Z".into())}).await?).unwrap(),
            serde_json::to_value(self.opportunity("00000000-0000-4000-8000-000000000071".into()).await?).unwrap(),
            serde_json::to_value(self.action_payload("00000000-0000-4000-8000-000000000071".into()).await?).unwrap(),
            serde_json::to_value(self.notifications(NotificationQuery{page:1,page_size:10,status:Some(NotificationStatus::Unread),priority:Some(NotificationPriority::High)}).await?).unwrap(),
            serde_json::to_value(self.read_notification("00000000-0000-4000-8000-000000000081".into()).await?).unwrap(),
            serde_json::to_value(self.read_all_notifications().await?).unwrap(),
        ];
        self.delete_bookmark(bookmark_id).await?;
        Ok(values)
    }

    pub(super) async fn product_test_action_payload(&self,id:&str)->Result<Value,BridgeError>{serde_json::to_value(self.action_payload(id.into()).await?).map_err(|_|BridgeError::local("invalid_response","Action payload could not be serialized"))}
    pub(super) async fn product_test_notifications(&self)->Result<Value,BridgeError>{serde_json::to_value(self.notifications(NotificationQuery{page:1,page_size:10,status:None,priority:None}).await?).map_err(|_|BridgeError::local("invalid_response","Notifications could not be serialized"))}
}

#[tauri::command] pub async fn bookmarks_list(bridge:State<'_,Bridge>,page:i64,page_size:i64)->Result<BookmarkPageView,BridgeError>{bridge.client()?.bookmarks(page,page_size).await}
#[tauri::command] pub async fn bookmarks_create(bridge:State<'_,Bridge>,input:BookmarkCreateInput)->Result<BookmarkView,BridgeError>{bridge.client()?.create_bookmark(input).await}
#[tauri::command] pub async fn bookmarks_update(bridge:State<'_,Bridge>,bookmark_id:String,input:BookmarkUpdateInput)->Result<BookmarkView,BridgeError>{bridge.client()?.update_bookmark(bookmark_id,input).await}
#[tauri::command] pub async fn bookmarks_delete(bridge:State<'_,Bridge>,bookmark_id:String)->Result<(),BridgeError>{bridge.client()?.delete_bookmark(bookmark_id).await}
#[tauri::command] pub async fn memory_search(bridge:State<'_,Bridge>,input:MemorySearchInput)->Result<MemorySearchView,BridgeError>{bridge.client()?.search_memory(input).await}
#[tauri::command] pub async fn opportunities_list(bridge:State<'_,Bridge>,input:OpportunityQuery)->Result<OpportunityPageView,BridgeError>{bridge.client()?.opportunities(input).await}
#[tauri::command] pub async fn opportunities_get(bridge:State<'_,Bridge>,opportunity_id:String)->Result<OpportunityView,BridgeError>{bridge.client()?.opportunity(opportunity_id).await}
#[tauri::command] pub async fn opportunities_action_payload(bridge:State<'_,Bridge>,opportunity_id:String)->Result<ActionPayloadView,BridgeError>{bridge.client()?.action_payload(opportunity_id).await}
#[tauri::command] pub async fn notifications_list(bridge:State<'_,Bridge>,input:NotificationQuery)->Result<NotificationPageView,BridgeError>{bridge.client()?.notifications(input).await}
#[tauri::command] pub async fn notifications_read(bridge:State<'_,Bridge>,notification_id:String)->Result<NotificationView,BridgeError>{bridge.client()?.read_notification(notification_id).await}
#[tauri::command] pub async fn notifications_read_all(bridge:State<'_,Bridge>)->Result<NotificationReadAllView,BridgeError>{bridge.client()?.read_all_notifications().await}
